$values.ConditionExpression:
@prefix cmw: <http://comindware.com/logics#>.
@prefix account: <http://comindware.com/ontology/account#>.
{
#Select current user
cmw:securityContext cmw:currentUser ?user.

#Define required user group
?g account:groupName "Диспетчеры".

#Check that selected user is a member of chosen group
if{?user account:userGroupMembership ?g.} 
then {true -> ?value.}
else {false -> ?value.}.
}
